request.query:
query CollectionDeleteState($id: ID!) {
          collection(id: $id) {
            id
            title
            handle
            resourcePublicationsCount { count }
            productsCount { count }
            summary: metafield(namespace: "custom", key: "summary") { value }
            intro_text: metafield(namespace: "custom", key: "intro_text") { value }
            faq: metafield(namespace: "custom", key: "faq") { value }
          }
        }
